const __dirname = path.dirname(__filename);

const publicHolidaysDir = path.join(__dirname, '../public/data/holidays');
const srcHolidaysPath = path.join(__dirname, '../src/data/holidays.json');

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-');
}

