// 1. Write to public/data/holidays/NP.json
fs.writeFileSync(
  path.join(publicHolidaysDir, 'NP.json'),
  JSON.stringify(allNepalRaw, null, 2),
  'utf8'
);
console.log(`✅ Wrote ${allNepalRaw.length} holidays for Nepal across 2021-2030 to public/data/holidays/NP.json`);

// 2. Also update dist/data/holidays/NP.json if dist exists
const distDir = path.join(__dirname, '../dist/data/holidays');
if (fs.existsSync(distDir)) {
  fs.writeFileSync(
    path.join(distDir, 'NP.json'),
    JSON.stringify(allNepalRaw, null, 2),
    'utf8'
  );
  console.log(`✅ Updated dist/data/holidays/NP.json`);
}

// 3. Update src/data/holidays.json
if (fs.existsSync(srcHolidaysPath)) {
  const srcData = JSON.parse(fs.readFileSync(srcHolidaysPath, 'utf8'));
  srcData.holidays = srcData.holidays.filter(h => h.countryCode !== 'NP').concat(allNepalRaw);
  fs.writeFileSync(srcHolidaysPath, JSON.stringify(srcData, null, 2), 'utf8');
  console.log(`✅ Updated src/data/holidays.json with Nepal holidays`);
}

// 4. Update public/data/holidays.json if it exists
const publicHolidaysJson = path.join(__dirname, '../public/data/holidays.json');
if (fs.existsSync(publicHolidaysJson)) {
  const pubData = JSON.parse(fs.readFileSync(publicHolidaysJson, 'utf8'));
  if (pubData.holidays) {
    pubData.holidays = pubData.holidays.filter(h => h.countryCode !== 'NP').concat(allNepalRaw);
    fs.writeFileSync(publicHolidaysJson, JSON.stringify(pubData, null, 2), 'utf8');
    console.log(`✅ Updated public/data/holidays.json with Nepal holidays`);
  }
}
